parameters.jsCode:
const raw = $json.output;

if (!raw) {
  throw new Error('Support Agent returned empty output.');
}

let support;

try {
  support = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  support = {
    issue: String(raw),
    category: 'general_query',
    priority: 'normal',
    sentiment: 'neutral',
    resolution: String(raw),
    human_handoff: false,
    approval_required: false
  };
}

return [{
  json: {
    ...$json,
    issue: String(support.issue || '').trim(),
    category: String(support.category || '').trim(),
    priority: String(support.priority || '').trim(),
    sentiment: String(support.sentiment || '').trim(),
    resolution: String(support.resolution || '').trim(),
    human_handoff: support.human_handoff === true,
    approval_required: support.approval_required === true
  }
}];

const data = $json;

return [{
  json: {
    ticket_id: 'TKT-' + String($execution.id),
    company_id: 'COMP001',
    session_id: String($execution.id),
    customer_name: '',
    email: '',
    issue: String(data.issue || '').trim(),
    category: String(data.category || '').trim(),
    priority: String(data.priority || '').trim(),
    sentiment: String(data.sentiment || '').trim(),
    resolution: String(data.resolution || '').trim(),
    human_handoff: data.human_handoff === true,
    status: 'new',
    created_at: new Date().toISOString()
  }
}];

return [{
  json: {
    output: "I’m sorry you’re experiencing this issue. I’ll connect you with a human support team member who can help you further."
  }
}];

const rows = $input.all();

if (rows.length === 0) {
  return [];
}

return [
  {
    json: rows[0].json
  }
];

